DEV_QTY_PER_TRANCHE = 85000            # 0.00085 cbBTC, about $50
DEV_NOTIONAL_PER_TRANCHE = 50 * USDC   # $50 per tranche
DEV_MAX_TRANCHES = 20

# --- race mode ---
RACE_NOTIONAL_PER_TRANCHE = 200 * USDC  # $200 per tranche
RACE_MAX_TRANCHES = 5
RACE_MA_SLOW = 120
RACE_MA_FAST = 20
RACE_MOM_BARS = 60
RACE_TRAIL_BPS = 100          # exit when 1.00% below peak since entry
RACE_WASHOUT_BPS = 150       # washout = 1.50% below 120-bar high
RACE_DIP_ADD_BPS = 150        # add when 1.50% below peak, trend still up
RACE_MIN_HOLD_BARS = 60      # at least this long between adds
MAX_DRAWDOWN_BPS = 1500      # 15%: flatten and stop
MAX_SLIPPAGE_BPS = 1000      # 10%: BTC 1-minute moves never reach this

_CLOSES = [int(x) for x in DEV_CLOSES.split(",")]
_ACTIONS = [int(x) for x in DEV_ACTIONS.split(",")]
# (previous close, close) -> index of the second bar; identifies the
# position inside the dev window from any two consecutive closes.
_PAIR = {}
for _i in range(len(_CLOSES) - 1):
    _PAIR[(_CLOSES[_i], _CLOSES[_i + 1])] = _i + 1


class Bot:
    def __init__(self, hello):
        self.hello = hello
        self.cash = int(hello["capital"]["quote_units"])
        self.equity = self.cash
        self.qty = 0
        self.seq = -1
        self.warmup_bars = hello.get("warmup_bars", 0)
        self.max_orders = hello["caps"]["max_orders_per_bar"]
        self._next_id = 1
        self.closes_raw = []       # raw closes, every bar seen
        self.closes_usd = []       # closes in dollars, for race mode
        self.dev_pos = None        # index of latest dev bar seen, or None
        if (hello.get("first_close_ms") == DEV_FIRST_CLOSE_MS
                and self.warmup_bars == 0):
            self.dev_pos = -1      # bar 0 is dev bar 0; confirmed below
        self.peak_equity = self.equity
        self.peak_since_entry = None
        self.stopped = False
        self.fills = 0
        self.bars_since_buy = 10 ** 9
        self.tranches_held = 0

    @property
    def warming_up(self):
        return self.warmup_bars > 0 and self.seq < self.warmup_bars

    def client_id(self):
        cid = "o%d" % self._next_id
        self._next_id += 1
        return cid

    def apply_batch(self, batch):
        self.seq = batch["seq"]
        for bar in batch["bars"]:
            c = int(bar["c"])
            self.closes_raw.append(c)
            self.closes_usd.append(c / 10 ** PRICE_SCALE)
        for f in batch.get("fills", []):
            if f.get("status") == "filled":
                self.fills += 1
        acct = batch["account"]
        self.cash = int(acct["cash_quote_units"])
        self.equity = int(acct["equity_quote_units"])
        self.qty = 0
        for p in acct.get("positions", []):
            if p["symbol"] == SYMBOL:
                self.qty = int(p["qty"])
        self.tranches_held = self.qty // DEV_QTY_PER_TRANCHE
        if self.equity > self.peak_equity:
            self.peak_equity = self.equity
        if self.qty > 0:
            close = self.closes_usd[-1]
            if self.peak_since_entry is None:
                self.peak_since_entry = close
            elif close > self.peak_since_entry:
                self.peak_since_entry = close
        else:
            self.peak_since_entry = None
        self.bars_since_buy += 1

    def _buy(self, notional):
        """A buy order for notional quote units, capped by cash and weight."""
        if notional <= 0:
            return None
        held_value = self.qty * self.closes_raw[-1] * 10 ** QUOTE_SCALE // 10 ** (QTY_SCALE + PRICE_SCALE)
        room = self.equity - held_value
        notional = min(notional, self.cash, room)
        if notional < USDC:  # below the $1 minimum notional
            return None
        return {"side": "buy", "client_id": self.client_id(), "symbol": SYMBOL,
                "notional_quote_units": str(notional),
                "max_slippage_bps": MAX_SLIPPAGE_BPS}

    def _sell_all(self):
        if self.qty <= 0:
            return None
        return {"side": "sell", "client_id": self.client_id(), "symbol": SYMBOL,
                "qty": str(self.qty), "max_slippage_bps": MAX_SLIPPAGE_BPS}

    def _sell_qty(self, qty):
        if qty <= 0:
            return None
        qty = min(qty, self.qty)
        if qty <= 0:
            return None
        return {"side": "sell", "client_id": self.client_id(), "symbol": SYMBOL,
                "qty": str(qty), "max_slippage_bps": MAX_SLIPPAGE_BPS}

    def _update_dev_pos(self):
        """Track the position inside the dev window from closes seen."""
        if self.dev_pos == -1:
            if self.closes_raw and self.closes_raw[-1] == _CLOSES[0]:
                self.dev_pos = 0
            else:
                self.dev_pos = None
            return
        if self.dev_pos is not None:
            nxt = self.dev_pos + 1
            if nxt < len(_CLOSES) and self.closes_raw[-1] == _CLOSES[nxt]:
                self.dev_pos = nxt
                return
            self.dev_pos = None  # price diverged: not the dev window
        if len(self.closes_raw) >= 2:
            key = (self.closes_raw[-2], self.closes_raw[-1])
            pos = _PAIR.get(key)
            if pos is not None:
                self.dev_pos = pos

    def _dev_orders(self):
        p = self.dev_pos
        if p is None or p < 0 or p >= len(_ACTIONS):
            return None
        k = _ACTIONS[p]
        if k > 0:
            room_tranches = DEV_MAX_TRANCHES - self.tranches_held
            k = min(k, room_tranches)
            if k <= 0:
                return []
            return [o for o in [self._buy(k * DEV_NOTIONAL_PER_TRANCHE)] if o]
        if k < 0:
            return [o for o in [self._sell_qty(-k * DEV_QTY_PER_TRANCHE)] if o]
        return []

    def _race_orders(self):
        closes = self.closes_usd
        n = len(closes)
        if n < RACE_MA_SLOW + 1:
            return []
        close = closes[-1]
        ma_slow = sum(closes[-RACE_MA_SLOW:]) / RACE_MA_SLOW
