        mom = close / closes[-RACE_MOM_BARS - 1] - 1.0
        high_slow = max(closes[-RACE_MA_SLOW:])
        orders = []
        holding = self.qty > 0
        # exits first: trailing stop, then trend flip
        if holding:
            if (self.peak_since_entry is not None
                    and close < self.peak_since_entry * (1 - RACE_TRAIL_BPS / 10000.0)):
                o = self._sell_all()
                return [o] if o else []
            if close < ma_slow * 0.99:
                o = self._sell_all()
                return [o] if o else []
